"""Goal GC guard table own_b_051 (PNC-019 C12-GC Method B; generated by scripts/pm-goal-gc-guard-tables.py --generate).

One owner predicate per row, in the complete checker's evaluation order. Every row of this table is
evaluated by exactly the same accepted complete calls. Predicates read only their own derived observation;
the checker derives each observation from the complete input and decides nothing itself.
"""
import pm_guard_isolation as g

FIELDS = ('result_origin', 'result_physical', 'result_original_source',)


def R01_result_origin(value, context):
    return 'result/origin' if value['result_origin'] is not True else None


def R02_result_physical(value, context):
    return 'result/physical' if value['result_physical'] is not True else None


def R03_result_original_source(value, context):
    return 'result/original_source' if value['result_original_source'] is not True else None


def case(value):
    context = None
    table = g.GuardTable([
        g.Guard('R01_result_origin', g.Invariant('/result_origin', 'owner predicate result/origin at scripts/pm_goal_own_b_oracles.py:550'), 'result/origin', R01_result_origin),
        g.Guard('R02_result_physical', g.Invariant('/result_physical', 'owner predicate result/physical at scripts/pm_goal_own_b_oracles.py:552'), 'result/physical', R02_result_physical),
        g.Guard('R03_result_original_source', g.Invariant('/result_original_source', 'owner predicate result/original_source at scripts/pm_goal_own_b_oracles.py:553'), 'result/original_source', R03_result_original_source),
    ])

    def check(value):
        table.require('R01_result_origin', value, context)
        table.require('R02_result_physical', value, context)
        table.require('R03_result_original_source', value, context)
        return True
    return g.Case(table, check, context)
